#include <string>
#include <algorithm>

class Solution {
public:
    std::string getLargestString(std::string s) {
        for (size_t i = 0; i + 1 < s.size(); ++i) {
            if (s[i] < s[i + 1] && ((s[i] - '0') % 2 == (s[i + 1] - '0') % 2)) {
                std::swap(s[i], s[i + 1]);
                break;
            }
        }
        return s;
    }
};

class Solution {
    public String getLargestString(String s) {
        char[] chars = s.toCharArray();
        for (int i = 0; i + 1 < chars.length; i++) {
            if (chars[i] < chars[i + 1] && ((chars[i] - '0') % 2 == (chars[i + 1] - '0') % 2)) {
                char tmp = chars[i];
                chars[i] = chars[i + 1];
                chars[i + 1] = tmp;
                break;
            }
        }
        return new String(chars);
    }
}

function getLargestString(s) {
    const chars = s.split('');
    for (let i = 0; i < chars.length - 1; i++) {
        if (chars[i] < chars[i + 1] && ((chars[i].charCodeAt(0) % 2) === (chars[i + 1].charCodeAt(0) % 2))) {
            const tmp = chars[i];
            chars[i] = chars[i + 1];
            chars[i + 1] = tmp;
            break;
        }
    }
    return chars.join('');
}
